const q = $json.query || {};
const service = String(q.service || '').toUpperCase().trim();
const site = String(q.site || '').toUpperCase().trim();
const dateDebut = String(q.dateDebut || '').trim();
const dateFin = String(q.dateFin || dateDebut || '').trim();
if (!/^[A-Z_]{2,30}$/.test(service)) throw new Error('Paramètre service invalide');
if (!/^[A-Z_]{2,30}$/.test(site)) throw new Error('Paramètre site invalide');
if (!/^\d{4}-\d{2}-\d{2}$/.test(dateDebut)) throw new Error('dateDebut doit être YYYY-MM-DD');
if (!/^\d{4}-\d{2}-\d{2}$/.test(dateFin)) throw new Error('dateFin doit être YYYY-MM-DD');
return [{json:{service,site,dateDebut,dateFin}}];
